/**
 * Void Ember — the belt's stones as Blender wrote them (void-ember-stone-models.js, generated by
 * scripts/blender/void_ember_stones.py): that the module decodes, that every model is a closed
 * body of about a unit across wound the right way, that its baked shading is in range, and that
 * the levels cost what the belt budgets for.
 */
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { VOID_EMBER_STONE_MODELS as MODELS } from '../../src/themes/void-ember/void-ember-stone-models.js';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const LEVELS = ['boulder', 'stone', 'gravel'];
const DESIGNS = ['potato', 'binary', 'shard', 'top', 'slab', 'bowl'];
/** Triangles a model of each level may have: enough to hold its shape, few enough for its count. */
const TRIANGLES = { boulder: [450, 700], stone: [80, 180], gravel: [24, 48] };

function decode(text, Type) {
    const bytes = Uint8Array.from(atob(text), (c) => c.charCodeAt(0));
    return new Type(bytes.buffer);
}

function read(model) {
    const positions = Array.from(decode(model.positions, Int16Array), (v) => v * MODELS.quant);
    return {
        positions,
        normals: Array.from(decode(model.normals, Int8Array), (v) => v / 127),
        shade: Array.from(decode(model.shade, Uint8Array), (v) => v / 255),
        index: Array.from(decode(model.index, Uint16Array)),
        at: (v) => positions.slice(v * 3, v * 3 + 3),
    };
}

const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];

const ALL = LEVELS.flatMap((level) => MODELS[level].map((model) => [`${level} ${model.design}`, level, model]));

describe('void ember stone models', () => {
    it('holds six designs as boulders and as stones, and two as gravel', () => {
        expect(MODELS.designs).toEqual(DESIGNS);
        expect(MODELS.boulder.map((m) => m.design)).toEqual(DESIGNS);
        expect(MODELS.stone.map((m) => m.design)).toEqual(DESIGNS);
        // Gravel is a few pixels: only "round" and "long" read apart, and every model is paid for
        // by every one of thousands of stones.
        expect(MODELS.gravel.length).toBeGreaterThanOrEqual(1);
        expect(MODELS.gravel.length).toBeLessThanOrEqual(2);
        expect(MODELS.quant).toBeGreaterThan(0);
        expect(Object.isFrozen(MODELS)).toBe(true);
    });

    it.each(ALL)('%s decodes to the counts it names, within its level\'s budget', (_name, level, model) => {
        const mesh = read(model);
        expect(mesh.positions).toHaveLength(model.vertexCount * 3);
        expect(mesh.normals).toHaveLength(model.vertexCount * 3);
        expect(mesh.shade).toHaveLength(model.vertexCount * 2);
        expect(mesh.index).toHaveLength(model.triangleCount * 3);
        expect(model.triangleCount).toBeGreaterThanOrEqual(TRIANGLES[level][0]);
        expect(model.triangleCount).toBeLessThanOrEqual(TRIANGLES[level][1]);
        expect([...mesh.positions, ...mesh.normals, ...mesh.shade].every(Number.isFinite)).toBe(true);
        expect(Math.max(...mesh.index)).toBe(model.vertexCount - 1);
        expect(Math.min(...mesh.index)).toBe(0);
        // Every vertex is used: a spare one is dead weight in every stone of the belt.
        expect(new Set(mesh.index).size).toBe(model.vertexCount);
    });

    it.each(ALL)('%s is a body about a unit across, centred, wound outward', (_name, _level, model) => {
        const mesh = read(model);
        let far = 0;
        const lo = [Infinity, Infinity, Infinity];
        const hi = [-Infinity, -Infinity, -Infinity];
        for (let v = 0; v < model.vertexCount; v++) {
            const p = mesh.at(v);
            far = Math.max(far, Math.hypot(...p));
            for (let k = 0; k < 3; k++) {
                lo[k] = Math.min(lo[k], p[k]);
                hi[k] = Math.max(hi[k], p[k]);
            }
        }
        // A bounding radius of one: the design's levels share a scale, and one of them reaches it.
        expect(far).toBeLessThanOrEqual(1 + 1e-4);
        expect(far).toBeGreaterThan(0.9);
        const size = hi.map((v, k) => v - lo[k]);
        // Never a needle or a sheet: the thinnest (the slab) still has a body.
        expect(Math.min(...size)).toBeGreaterThan(0.25);
        expect(Math.max(...size)).toBeGreaterThan(1.4);
        // Its middle is near the origin (the tumble turns it about there).
        expect(Math.hypot(...lo.map((v, k) => (v + hi[k]) / 2))).toBeLessThan(0.3);
        // Wound counter-clockwise seen from outside: a positive volume, and no collapsed face.
        let volume = 0;
        let area = 0;
        let thin = 0;
        for (let t = 0; t < mesh.index.length; t += 3) {
            const [a, b, c] = [mesh.at(mesh.index[t]), mesh.at(mesh.index[t + 1]), mesh.at(mesh.index[t + 2])];
            volume += dot(a, cross(b, c)) / 6;
            const n = cross(sub(b, a), sub(c, a));
            const twice = Math.hypot(...n);
            area += twice / 2;
            if (twice < 1e-7) thin += 1;
        }
        expect(volume).toBeGreaterThan(0.15);
        expect(volume).toBeLessThan((4 / 3) * Math.PI);
        expect(area).toBeGreaterThan(2);
        expect(thin).toBe(0);
    });

    it.each(ALL)('%s carries the fine surface\'s normals and shading', (_name, level, model) => {
        const mesh = read(model);
        // Unit normals (eight bits a component), which agree with the faces they shade.
        for (let v = 0; v < model.vertexCount; v++) {
            const n = mesh.normals.slice(v * 3, v * 3 + 3);
            expect(Math.hypot(...n)).toBeGreaterThan(0.9);
            expect(Math.hypot(...n)).toBeLessThan(1.1);
        }
        let agree = 0;
        let corners = 0;
        for (let t = 0; t < mesh.index.length; t += 3) {
            const [ia, ib, ic] = mesh.index.slice(t, t + 3);
            const face = cross(sub(mesh.at(ib), mesh.at(ia)), sub(mesh.at(ic), mesh.at(ia)));
            const length = Math.hypot(...face) || 1;
            for (const v of [ia, ib, ic]) {
                agree += dot(face, mesh.normals.slice(v * 3, v * 3 + 3)) / length;
                corners += 1;
            }
        }
        // (The coarser the level, the further its few faces stand from the surface they were cut from.)
        expect(agree / corners).toBeGreaterThan({ boulder: 0.8, stone: 0.7, gravel: 0.6 }[level]);
        const ao = mesh.shade.filter((_, i) => i % 2 === 0);
        const crest = mesh.shade.filter((_, i) => i % 2 === 1);
        // Mostly open to the sky, darker somewhere (a crater, a neck, a hollow) on the finer levels.
        expect(Math.max(...ao)).toBeGreaterThan(0.9);
        expect(Math.min(...ao)).toBeGreaterThanOrEqual(0);
        expect(ao.reduce((sum, v) => sum + v, 0) / ao.length).toBeGreaterThan(0.6);
        expect(Math.max(...crest)).toBeGreaterThan(0.55);
        if (level === 'boulder') {
            // Crests and crevices both sides of flat (0.5); a coarser level's bake is a mean over
            // so much of the body that it is all crest.
            expect(Math.min(...crest)).toBeLessThan(0.45);
            expect(Math.max(...crest)).toBeGreaterThan(0.7);
            // ...and every design but the splinter (it has no hollow at all) shades itself somewhere.
            if (model.design !== 'shard') expect(Math.min(...ao)).toBeLessThan(0.95);
        }
    });

    it('tells the six designs apart by their proportions', () => {
        // The longest and the shortest extent of each boulder's oriented box (its own axes are the
        // design's): a splinter is long and thin, a slab flat, a top and a half shell squat.
        const extents = Object.fromEntries(MODELS.boulder.map((model) => {
            const mesh = read(model);
            const size = [0, 1, 2].map((k) => {
                const values = [];
                for (let v = 0; v < model.vertexCount; v++) values.push(mesh.positions[v * 3 + k]);
                return Math.max(...values) - Math.min(...values);
            }).sort((a, b) => a - b);
            return [model.design, size];
        }));
        // The splinter: at least twice as long as it is wide either way.
        expect(extents.shard[2] / extents.shard[1]).toBeGreaterThan(1.9);
        // The slab: thin one way, broad the other two.
        expect(extents.slab[0] / extents.slab[1]).toBeLessThan(0.55);
        // The binary and the potato: long, but with a body.
        expect(extents.binary[2] / extents.binary[0]).toBeGreaterThan(1.5);
        expect(extents.potato[2] / extents.potato[0]).toBeGreaterThan(1.4);
        // The top and the half shell: squat, as broad one way as the other.
        expect(extents.top[2] / extents.top[1]).toBeLessThan(1.25);
        expect(extents.bowl[2] / extents.bowl[1]).toBeLessThan(1.25);
        expect(extents.bowl[0] / extents.bowl[2]).toBeLessThan(0.8);
    });

    it('is a small module, generated by the Blender script', () => {
        const file = path.join(root, 'src/themes/void-ember/void-ember-stone-models.js');
        const source = readFileSync(file, 'utf8');
        expect(source).toMatch(/GENERATED by scripts\/blender\/void_ember_stones\.py/);
        expect(source.length).toBeLessThan(120 * 1024);
        expect(readFileSync(path.join(root, 'scripts/blender/void_ember_stones.py'), 'utf8'))
            .toMatch(/void-ember-stone-models\.js/);
    });
});
